def json_stringify(obj):
    # Helper to escape necessary characters in strings
    def escape_string(s):
        # Escape backslash, double quote, and the common control characters
        return (s.replace('\\', '\\\\').replace('"', '\\"')
                 .replace('\n', '\\n').replace('\r', '\\r').replace('\t', '\\t'))

    # Handle string
    if isinstance(obj, str):
        return '"' + escape_string(obj) + '"'

    # Handle booleans and None (null) BEFORE numbers, since bool is a subclass of int
    if obj is True:
        return 'true'
    if obj is False:
        return 'false'
    if obj is None:
        return 'null'
    # Handle numbers (int, float)
    if isinstance(obj, (int, float)):
        return str(obj)

    # Handle arrays (lists, tuples)
    if isinstance(obj, (list, tuple)):
        # Recursively serialize each element
        elements = [json_stringify(item) for item in obj]
        return '[' + ','.join(elements) + ']'

    # Handle objects (dict)
    if isinstance(obj, dict):
        items = []
        for key in obj:
            # Keys must be strings in JSON
            key_str = '"' + escape_string(str(key)) + '"'
            value_str = json_stringify(obj[key])
            items.append(key_str + ':' + value_str)
        return '{' + ','.join(items) + '}'

    # Catch-all for unsupported types
    raise TypeError(f"Type {type(obj)} not supported")
